```ts
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

export class ChatRoom extends DurableObject<Env> {
  // Tail of the write queue. Every operation runs after the previous one settles.
  private queue: Promise<unknown> = Promise.resolve();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    void this.ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS room_state (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL,
          updated_at INTEGER NOT NULL
        )
      `);
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  private serialize<T>(task: () => T | Promise<T>): Promise<T> {
    const run = this.queue.then(() => task());
    this.queue = run.catch(() => undefined);
    return run;
  }

  async setState(key: string, value: unknown): Promise<void> {
    await this.serialize(() => {
      this.ctx.storage.sql.exec(
        `INSERT INTO room_state (key, value, updated_at) VALUES (?, ?, ?)
         ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
        key,
        JSON.stringify(value),
        Date.now(),
      );
    });
  }

  // Read-modify-write under the queue. The callback runs with no other write in flight.
  async update<T>(key: string, fn: (current: T | null) => T): Promise<T> {
    return this.serialize(() => {
      const row = this.ctx.storage.sql
        .exec<{ value: string }>("SELECT value FROM room_state WHERE key = ?", key)
        .toArray()[0];
      const next = fn(row ? (JSON.parse(row.value) as T) : null);
      this.ctx.storage.sql.exec(
        `INSERT INTO room_state (key, value, updated_at) VALUES (?, ?, ?)
         ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
        key,
        JSON.stringify(next),
        Date.now(),
      );
      return next;
    });
  }

  // Queued like the writes, so a read sees every write accepted before it.
  async getState<T>(key: string): Promise<T | null> {
    return this.serialize(() => {
      const row = this.ctx.storage.sql
        .exec<{ value: string }>("SELECT value FROM room_state WHERE key = ?", key)
        .toArray()[0];
      return row ? (JSON.parse(row.value) as T) : null;
    });
  }

  async alarm(): Promise<void> {
    // Reschedule before the work so a failure in the hook does not stop the hourly cadence.
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
    await this.serialize(() => this.onHourly());
  }

  // Hourly work goes here. It runs inside the write queue.
  private onHourly(): void {}
}
```

Wrangler config for the binding and the SQLite-backed class:

```jsonc
{
  "durable_objects": {
    "bindings": [{ "name": "CHAT_ROOM", "class_name": "ChatRoom" }]
  },
  "migrations": [{ "tag": "v1", "new_sqlite_classes": ["ChatRoom"] }]
}
```

Callers route to a room with `env.CHAT_ROOM.getByName(roomId)`.

The class serializes writes with an in-memory promise chain and runs every read and write through it, so reads see earlier writes. `update()` does a read-modify-write inside the queue. The alarm reschedules itself before running `onHourly()`, and the constructor schedules the first alarm only when none exists. I have not run this against a Worker, and I did not check the `sql.exec` generic signature against the current docs.
